code.cpp:
class Solution {
public:
    vector<int> minDifference(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<array<int,101>> prefix(n + 1);
        for (int v = 0; v <= 100; v++) prefix[0][v] = 0;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i];
            prefix[i + 1][nums[i]]++;
        }
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            int prev = -1;
            int best = INT_MAX;
            for (int v = 1; v <= 100; v++) {
                if (prefix[r + 1][v] - prefix[l][v] > 0) {
                    if (prev != -1 && v - prev < best) best = v - prev;
                    prev = v;
                }
            }
            ans.push_back(best == INT_MAX ? -1 : best);
        }
        return ans;
    }
};
